import { v4 as uuidv4 } from "uuid";
import type { PropertyOption } from "@shared/types/documentProperties";

/**
 * Creates a new select option. Option IDs are generated by the client so that
 * values can reference an option before the definition is saved; this is the
 * only place they are created.
 *
 * @param label the label of the option.
 * @returns the new option.
 */
export function newPropertyOption(label: string): PropertyOption {
  return { id: uuidv4(), label: label.trim() };
}
